#!/usr/bin/env python3
"""drug/aizynth_retrosynthesis — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "aizynth_retrosynthesis"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'aizynth_retrosynthesis', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """AiZynthFinder 4.4.1 retrosynthesis — host_env=praxis-drug。
    输入:target_smiles / max_steps (default 6) / time_limit_s (default 120)
    输出:n_routes / shortest_route_steps / routes[]
    """
    import os as _os
    import tempfile as _tempfile
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    target = payload.get("target_smiles") or payload.get("smiles")
    max_steps = int(payload.get("max_steps", 6))
    time_limit = int(payload.get("time_limit_s", 120))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "target": target, "max_steps": max_steps}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_routes": 0, "shortest_route_steps": 0,
                "routes": [], "diagnostics": {**diagnostics, "dry": True}}
    if not target:
        return {"ok": False, "error": "需要 target_smiles", "diagnostics": diagnostics}

    script = (
        "import json, sys\n"
        "from aizynthfinder.aizynthfinder import AiZynthFinder\n"
        f"target = {target!r}; max_steps = {max_steps}; t_limit = {time_limit}\n"
        "config_paths = ['/home/zkyd/.aizynth/config.yml',\n"
        "                '/home/zkyd/data1/aizynth/config.yml']\n"
        "import os\n"
        "cfg = next((p for p in config_paths if os.path.isfile(p)), None)\n"
        "if cfg is None:\n"
        "    json.dump({'__err': 'aizynth config not found',\n"
        "               'tried': config_paths}, sys.stdout); sys.exit(0)\n"
        "finder = AiZynthFinder(configfile=cfg)\n"
        "finder.target_smiles = target\n"
        "finder.config.search.algorithm = 'mcts'\n"
        "finder.config.search.iteration_limit = 100\n"
        "finder.config.search.time_limit = t_limit\n"
        "finder.config.search.max_transforms = max_steps\n"
        "finder.tree_search()\n"
        "finder.build_routes()\n"
        "stats = finder.extract_statistics()\n"
        "json.dump({'n_routes': stats.get('number_of_routes', 0),\n"
        "           'shortest_route_steps': stats.get('shortest_route', {}).get('len', 0),\n"
        "           'is_solved': stats.get('is_solved', False),\n"
        "           'routes': []}, sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=time_limit + 60)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "aizynth 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    if "__err" in parsed:
        return {"ok": False, "error": parsed["__err"], "diagnostics": {**diagnostics, **parsed}}
    return {"ok": True, "skill_id": SKILL, **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
